57	function signalRunningProcess(
58	  running: Pick<RunningProcess, "child" | "processGroupId">,
59	  signal: NodeJS.Signals,
60	) {
61	  if (process.platform !== "win32" && running.processGroupId && running.processGroupId > 0) {
62	    try {
63	      process.kill(-running.processGroupId, signal);
64	      return;
65	    } catch {
66	      // Fall back to the direct child signal if group signaling fails.
67	    }
68	  }
69	  if (!running.child.killed) {
70	    running.child.kill(signal);
71	  }
72	}
