160	function resolveInstalledEntryTarget(
161	  skillsHome: string,
162	  entryName: string,
163	  dirent: Dirent,
164	  linkedPath: string | null,
165	): InstalledSkillTarget {
166	  const fullPath = path.join(skillsHome, entryName);
167	  if (dirent.isSymbolicLink()) {
168	    return {
169	      targetPath: linkedPath ? path.resolve(path.dirname(fullPath), linkedPath) : null,
170	      kind: "symlink",
