419	  const sourceRunId = asString(continuation.sourceRunId, "").trim() || null;
420	  const state = asString(continuation.state, "").trim() || null;
421	  const reason = asString(continuation.reason, "").trim() || null;
422	  const instruction = asString(continuation.instruction, "").trim() || null;
423	  if (!attempt && !maxAttempts && !sourceRunId && !state && !reason && !instruction) return null;
424	  return {
425	    attempt: attempt > 0 ? attempt : null,
426	    maxAttempts: maxAttempts > 0 ? maxAttempts : null,
427	    sourceRunId,
428	    state,
429	    reason,
