485	  const allowedActions = Array.isArray(stage.allowedActions)
486	    ? stage.allowedActions
487	        .filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0)
488	        .map((entry) => entry.trim())
489	    : [];
490	  const currentParticipant = normalizePaperclipWakeExecutionPrincipal(stage.currentParticipant);
491	  const returnAssignee = normalizePaperclipWakeExecutionPrincipal(stage.returnAssignee);
492	  const reviewRequestRaw = parseObject(stage.reviewRequest);
493	  const reviewInstructions = asString(reviewRequestRaw.instructions, "").trim();
494	  const reviewRequest = reviewInstructions ? { instructions: reviewInstructions } : null;
495	  const stageId = asString(stage.stageId, "").trim() || null;
496	  const stageType = asString(stage.stageType, "").trim() || null;
497	  const lastDecisionOutcome = asString(stage.lastDecisionOutcome, "").trim() || null;
498	
499	  if (!wakeRole && !stageId && !stageType && !currentParticipant && !returnAssignee && !reviewRequest && !lastDecisionOutcome && allowedActions.length === 0) {
500	    return null;
501	  }
502	
